import matplotlib.pyplot as plt

import config

INK = "#0b0b0b"
INK_SOFT = "#52514e"
GRID = "#e4e3df"
SURFACE = "#fcfcfb"
# Fixed order. A model keeps its color in every chart.
SERIES = ["#2a78d6", "#eb6834", "#1baf7a", "#eda100"]
MODEL_COLORS = {"Naive Bayes": SERIES[0], "kNN (distance-weighted)": SERIES[1],
                "Random Forest": SERIES[2], "Neural network": SERIES[3]}
STEP_LABELS = {"1_filings_only": "Filings only", "2_plus_pluto": "+ PLUTO",
               "3_plus_violations": "+ Violations"}


def new_axes(title, xlabel="", ylabel="", size=(7.5, 4.2)):
    fig, ax = plt.subplots(figsize=size, facecolor=SURFACE)
    ax.set_facecolor(SURFACE)
    ax.set_title(title, loc="left", color=INK, fontsize=12, fontweight="bold", pad=12)
    ax.set_xlabel(xlabel, color=INK_SOFT)
    ax.set_ylabel(ylabel, color=INK_SOFT)
    for side in ("top", "right"):
        ax.spines[side].set_visible(False)
    for side in ("left", "bottom"):
        ax.spines[side].set_color(GRID)
    ax.tick_params(colors=INK_SOFT, length=0)
    ax.grid(axis="y", color=GRID, linewidth=0.8)
    ax.set_axisbelow(True)
    return fig, ax


def line(ax, x, y, label, color):
    ax.plot(x, y, color=color, linewidth=2, marker="o", markersize=6,
            markeredgecolor=SURFACE, markeredgewidth=1.5, label=label)


def legend(ax):
    ax.legend(frameon=False, labelcolor=INK, loc="best")


def bars(ax, labels, values, color=SERIES[0]):
    """Horizontal bars, largest at the top."""
    ax.barh(list(labels)[::-1], list(values)[::-1], color=color, height=0.6)
    ax.grid(axis="y", visible=False)
    ax.grid(axis="x", color=GRID, linewidth=0.8)
    ax.tick_params(axis="y", colors=INK)


def comparison_chart(table, metric="roc_auc", models=None):
    """One line per model across the three feature steps."""
    models = models or list(MODEL_COLORS)
    steps = [s for s in STEP_LABELS if s in set(table["step"])]
    fig, ax = new_axes("Does adding building and violation data help?",
                       ylabel=f"Test {metric.replace('_', ' ').upper()}")
    x = range(len(steps))
    ends = []
    for i, model in enumerate(models):
        rows = table[table["model"] == model].set_index("step")
        y = [rows[metric].get(s, float("nan")) for s in steps]
        color = MODEL_COLORS.get(model, SERIES[i % len(SERIES)])
        line(ax, x, y, model, color)
        if len(y) and y[-1] == y[-1]:
            ends.append(y[-1])
    # Value labels at the right end, pushed apart so close scores stay readable.
    low, high = ax.get_ylim()
    gap, last = (high - low) * 0.05, None
    for value in sorted(ends):
        at = value if last is None else max(value, last + gap)
        ax.annotate(f"{value:.3f}", (x[-1], at), xytext=(8, 0),
                    textcoords="offset points", va="center", color=INK, fontsize=9)
        last = at
    if metric == "roc_auc":
        ax.axhline(config.PUBLISHED_ROC_AUC, color=INK_SOFT, linewidth=1, linestyle="--")
        ax.annotate(f"Published filings-only model: {config.PUBLISHED_ROC_AUC}",
                    (0, config.PUBLISHED_ROC_AUC), xytext=(0, 5),
                    textcoords="offset points", color=INK_SOFT, fontsize=9)
    ax.set_xticks(list(x), [STEP_LABELS[s] for s in steps])
    ax.set_xlim(-0.2, len(steps) - 0.6)
    legend(ax)
    return fig, ax


def rate_bars(df, column, title, label="is_unsafe", top=12):
    """Share of filings rated Unsafe for each value of one column."""
    stats = df.groupby(column, observed=True)[label].agg(["mean", "size"])
    stats = stats.sort_values("mean", ascending=False).head(top)
    fig, ax = new_axes(title, xlabel="Share rated Unsafe",
                       size=(7.5, 0.42 * len(stats) + 1.6))
    names = [f"{name}  (n={n:,})" for name, n in zip(stats.index, stats["size"])]
    bars(ax, names, stats["mean"].values)
    ax.axvline(df[label].mean(), color=INK_SOFT, linewidth=1, linestyle="--")
    ax.xaxis.set_major_formatter(lambda v, _: f"{v:.0%}")
    return fig, ax
